1	// Live phone agent for Pawse. There is NO telephony: the German script and the numbers come from
2	// the backend (GET /api/v1/demo/mimi), every AI line is spoken with the same Gradium German voice
3	// (POST /api/v1/voice/speech, only with explicit consent), and every callee reply and the result
4	// stay marked `simulated: true`. Nothing is ever dialled or booked. Implements ../contracts.js.
5	//
6	// One call = one server-issued call id: the first AI line carries the AI disclosure and the server
7	// answers with an X-Pawse-Call-Id header; later lines send that id so the server does not repeat
8	// the disclosure. If Gradium fails (no key, 503, network), the rest of the call uses browser speech
9	// so the voice never flips back and forth.
10	
11	import { PHONE_AGENT_URL } from '../config.js';
12	import { speak, stopSpeech, isSpeechMuted, resolveVoiceName } from './speech.js';
13	import { phoneVoiceEvent } from './providers.js';
14	
15	// Must equal DISCLOSURE in pawse/voice.py so the server does not prepend a second greeting.
16	const DISCLOSURE = 'Guten Tag, hier ist Pawse, die KI-Assistenz im Auftrag der Katzenhalterin oder des Katzenhalters.';
17	const FIRST_LINE = {
18	  original: `${DISCLOSURE} Ich bin ein KI-Assistent und kein Mensch.`,
19	  text: {
20	    en: 'Hello, this is Pawse, the AI assistant calling on behalf of the cat owner. I am an AI assistant, not a person.',
21	    zh: '您好，我是 Pawse，受猫主人委托的 AI 助手。我是 AI 助手，不是真人。',
22	  },
23	};
24	const STEP_INDEX = { vet: 2, insurance: 3 };
25	const T = (en, zh) => ({ en, zh });
26	
27	const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : d);
28	
29	async function fetchStory(base) {
30	  const res = await fetch(`${base}/api/v1/demo/mimi`);
31	  if (!res.ok) throw new Error(`demo story unavailable (${res.status})`);
32	  return res.json();
33	}
34	
35	/**
36	 * Fetches Gradium audio for the AI lines of one call, strictly in order (the first response
37	 * carries the call id the later ones need). Each line is fetched at most once, so the page can
38	 * preload the next AI line while the current one plays.
39	 */
40	function createGradiumLines(base, voice, state) {
41	  const cache = new Map();
42	  let chain = Promise.resolve();
43	  let callId = null;
44	  let failed = false;
45	
46	  const request = async (text) => {
47	    if (failed || state.ended) return null;
48	    try {
49	      const res = await fetch(`${base}/api/v1/voice/speech`, {
50	        method: 'POST',
51	        headers: { 'Content-Type': 'application/json' },
52	        body: JSON.stringify({ text, language: 'de', voice, share_with_gradium: true, ...(callId ? { call_id: callId } : {}) }),
53	      });
54	      if (!res.ok) throw new Error(`speech ${res.status}`);
55	      const id = res.headers && typeof res.headers.get === 'function' ? res.headers.get('x-pawse-call-id') : null;
56	      if (id) callId = id;
57	      return await res.blob();
58	    } catch {
59	      failed = true; // stay on browser speech for the rest of this call
60	      return null;
61	    }
62	  };
63	
64	  return {
65	    get failed() {
66	      return failed;
67	    },
68	    /** Promise<Blob|null> for line `key`; queued behind every earlier request. */
69	    fetch(key, text) {
70	      if (!cache.has(key)) {
71	        const p = chain.then(() => request(text));
72	        chain = p;
73	        cache.set(key, p);
74	      }
75	      return cache.get(key);
76	    },
77	  };
78	}
79	
80	/** Plays one audio blob. Resolves true if it played to the end, false to fall back. */
81	function playBlob(blob, state) {
82	  if (!blob || state.ended || typeof Audio === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) {
83	    return Promise.resolve(false);
84	  }
85	  return new Promise((resolve) => {
86	    let url;
87	    try {
88	      url = URL.createObjectURL(blob);
89	    } catch {
90	      resolve(false);
91	      return;
92	    }
93	    const a = new Audio(url);
94	    state.audio = a;
95	    const done = (ok) => {
96	      if (state.audio === a) state.audio = null;
97	      try { URL.revokeObjectURL(url); } catch { /* ignore */ }
98	      resolve(ok);
99	    };
100	    a.onended = () => done(true);
101	    a.onerror = () => done(false);
102	    try {
103	      const p = a.play();
104	      if (p && p.catch) p.catch(() => done(false));
105	    } catch {
106	      done(false);
107	    }
108	  });
109	}
110	
111	function buildVetResult(story, lang, context) {
112	  const c = story.costs || {};
113	  return {
114	    kind: 'appointment',
115	    time: story.calendar?.appointment || '16:30',
116	    place: context.clinic?.name || (lang === 'zh' ? '诊所（演示）' : 'Clinic (demo)'),
117	    estimate: num(c.treatment, 600),
118	    currency: c.currency || 'CHF',
119	    note:
120	      lang === 'zh'
121	        ? '模拟：这是演示脚本，没有真的打电话，也没有真的预约。上门另加约 150 瑞郎。'
122	        : 'Simulated: demo script, no real call was made and nothing was booked. A home visit would add about CHF 150.',
123	    simulated: true,
124	  };
125	}
126	
127	function buildInsuranceResult(story, lang) {
128	  const c = story.costs || {};
129	  const deductible = num(c.remaining_deductible, 300);
130	  const rate = num(c.reimbursement_rate, 0.8);
131	  const estimate = num(c.treatment, 600);
132	  const reimbursed = num(c.reimbursed, Math.max(estimate - deductible, 0) * rate);
133	  const cur = c.currency || 'CHF';
134	  const zh = lang === 'zh';
135	  const clinic = num(c.clinic, 385);
136	  const home = num(c.home, 510);
137	  return {
138	    kind: 'coverage',
139	    covered: true,
140	    currency: cur,
141	    deductible,
142	    rate,
143	    estimate,
144	    reimbursed,
145	    outOfPocket: estimate - reimbursed,
146	    points: [
147	      { ok: true, text: zh ? '意外从第一天起就保' : 'Accident covered from day 1' },
148	      {
149	        ok: true,
150	        text: zh
151	          ? `先付前 ${deductible} 瑞郎，之后报销 ${Math.round(rate * 100)}%`
152	          : `You pay the first ${cur} ${deductible}, then ${Math.round(rate * 100)}% is reimbursed`,
153	      },
154	      { ok: false, text: zh ? '上门费不保' : 'Home visit not covered', ref: 'AVB 1.2' },
155	      { ok: false, text: zh ? '之后的理疗不保' : 'Physiotherapy not covered', ref: 'AVB 1.2' },
156	      {
157	        ok: true,
158	        text: zh
159	          ? `估算自付：诊所约 ${cur} ${clinic}，上门约 ${cur} ${home}（含出租车 / 上门费）`
160	          : `Estimated cost to you: clinic about ${cur} ${clinic} vs home visit about ${cur} ${home}`,
161	      },
162	    ],
163	    simulated: true,
164	  };
165	}
166	
167	export function createLivePhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
168	  const base = PHONE_AGENT_URL || '';
169	  const listeners = new Set();
170	  const timers = new Set();
171	  const state = { ended: false, audio: null };
172	  let started = false;
173	
174	  const emit = (e) => {
175	    if (!state.ended) listeners.forEach((l) => l(e));
176	  };
177	  const wait = (ms) =>
178	    new Promise((resolve) => {
179	      const id = setTimeout(() => {
180	        timers.delete(id);
181	        resolve();
182	      }, ms / speed);
183	      timers.add(id);
184	    });
185	
186	  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true);
187	  // the page may withdraw or give it mid-call with setGradiumConsent().
188	  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';
189	  let gradiumConsent = context.gradiumConsent === true;
190	  const gradium = createGradiumLines(base, voice, state);
191	  const useGradium = () => gradiumConsent && !gradium.failed && !isSpeechMuted() && typeof fetch === 'function';
192	
193	  // Tell the page which voice Pawse really uses; only emits when it changes (e.g. Gradium fails -> browser).
194	  let lastVoice = '';
195	  const announceVoice = (gradiumOk) => {
196	    const ev = phoneVoiceEvent({ gradiumOk, muted: isSpeechMuted(), variant: voice, browser: resolveVoiceName('de') });
197	    const sig = JSON.stringify(ev);
198	    if (sig !== lastVoice) {
199	      lastVoice = sig;
200	      emit(ev);
201	    }
202	  };
203	
204	  async function say(lines, i) {
205	    const line = lines[i];
206	    if (line.who === 'ai' && !useGradium()) announceVoice(false);
207	    if (line.who === 'ai' && useGradium()) {
208	      const blob = await gradium.fetch(i, line.original);
209	      // Preload the next AI line while this one plays.
