30	  return (
31	    <div className="result-card">
32	      <h3>{t.insuranceAnswer}</h3>
33	      {result.simulated && <span className="sim-badge">{t.simulated}</span>}
34	      <ul className="cov">
35	        {result.points.map((p, i) => (
36	          <li key={i} className={p.ok ? 'ok' : 'no'}>
37	            <span className="cov-icon" aria-hidden="true">{p.ok ? '✓' : '✕'}</span>
38	            <span>
39	              {p.text}
40	              {p.ref && <span className="ref">{p.ref}</span>}
41	            </span>
42	          </li>
43	        ))}
44	      </ul>
45	      <div className="money">
46	        <div>
47	          <span className="muted small">{t.reimbursed}</span>
48	          <strong>≈ {cur} {result.reimbursed}</strong>
49	        </div>
50	        <div>
51	          <span className="muted small">{t.outOfPocket}</span>
52	          <strong className="accent">≈ {cur} {result.outOfPocket}</strong>
53	        </div>
54	      </div>
55	    </div>
56	  );
57	}
58	
59	// The owner only ever deals in English (their language): Pawse talks German with the clinic or
60	// insurer in the background. The screen shows progress steps, questions that need the owner's
61	// decision, and the result. The German transcript and audio are there on request, never in the way.
62	export default function PhoneCall({ t, lang, target, clinic, context, gradium, rail, onDone }) {
63	  const base = t.callees[target];
64	  const callee = clinic
65	    ? { ...base, name: clinic.name, role: `${clinic.distanceKm.toFixed(1)} km` }
66	    : base;
67	  const [status, setStatus] = useState('dialing');
68	  const [lines, setLines] = useState([]);
69	  const [steps, setSteps] = useState([]); // [{ text } | { chose: label }], in call order
70	  const [question, setQuestion] = useState(null);
71	  const [speaking, setSpeaking] = useState('none');
72	  const [result, setResult] = useState(null);
73	  const [error, setError] = useState('');
74	  const [secs, setSecs] = useState(0);
75	  const [listening, setListening] = useState(false);
76	  // Pawse's real voice, updated by the agent's 'provider' events (e.g. Gradium -> browser fallback).
77	  const [voice, setVoice] = useState(() =>
78	    IS_LIVE_PHONE && gradium && gradium.on ? { voice: 'gradium', variant: context && context.voice } : null
79	  );
80	  const [browser, setBrowser] = useState(() => resolveVoiceName('de'));
81	  useEffect(() => {
82	    const refresh = () => setBrowser(resolveVoiceName('de'));
83	    return onVoicesChanged(refresh);
84	  }, []);
85	  const callRef = useRef(null);
86	  const listRef = useRef(null);
87	  const resultRef = useRef(null);
88	  const questionRef = useRef(null);
89	  resultRef.current = result;
90	  questionRef.current = question;
91	
92	  useEffect(() => {
93	    const call = createPhoneCall({ target, lang, context });
94	    callRef.current = call;
95	    const off = call.on((e) => {
96	      switch (e.type) {
97	        case 'status':
98	          setStatus(e.state);
99	          break;
100	        case 'speaking':
101	          setSpeaking(e.who);
102	          break;
103	        case 'provider':
104	          if (e.step === 'voice') setVoice(e);
105	          break;
106	        case 'line':
107	          setLines((p) => [...p, e]);
108	          break;
109	        case 'progress':
110	          setSteps((p) => [...p, { text: e.text }]);
111	          break;
112	        case 'question':
113	          setQuestion(e);
114	          break;
115	        case 'answered': {
116	          const q = questionRef.current;
117	          if (q && q.id === e.id) {
118	            const opt = q.options.find((o) => o.id === e.optionId);
119	            setSteps((p) => [...p, { chose: opt ? opt.label : e.optionId }]);
120	            setQuestion(null);
121	          }
122	          break;
123	        }
124	        case 'result': {
125	          const { type, ...r } = e;
126	          const problems = validateResult(target, r);
127	          if (problems.length) console.warn('[Pawse] call result violates the contract:', problems, r);
128	          setResult(r);
129	          break;
130	        }
131	        case 'error':
132	          setError(e.message || '');
133	          break;
134	        default:
135	          break;
136	      }
137	    });
138	    call.start();
139	    return () => {
140	      off();
141	      call.hangup();
142	    };
143	    // context is captured once per call on purpose
144	    // eslint-disable-next-line react-hooks/exhaustive-deps
145	  }, [target, lang]);
146	
147	  useEffect(() => {
148	    if (status !== 'connected') return undefined;
149	    const id = setInterval(() => setSecs((s) => s + 1), 1000);
150	    return () => clearInterval(id);
151	  }, [status]);
152	
153	  useEffect(() => {
154	    const el = listRef.current;
155	    if (el) el.scrollTop = el.scrollHeight;
156	  }, [steps, question, result]);
157	
158	  const hangup = () => {
159	    callRef.current && callRef.current.hangup();
160	    onDone(resultRef.current);
161	  };
162	
163	  const choose = (optionId) => {
164	    if (question && callRef.current && callRef.current.answer) callRef.current.answer(question.id, optionId);
165	  };
166	
167	  const toggleListen = () => {
168	    const next = !listening;
169	    setListening(next);
170	    callRef.current && callRef.current.setListening && callRef.current.setListening(next);
171	  };
172	
173	  const toggleGradium = () => {
174	    const next = !gradium.on;
175	    gradium.set(next);
176	    callRef.current && callRef.current.setGradiumConsent && callRef.current.setGradiumConsent(next);
177	  };
178	
179	  const live = status !== 'ended' && !result;
180	  const statusText = status === 'dialing' ? t.dialing : status === 'connected' ? `${t.inCall} · ${fmt(secs)}` : t.callEnded;
181	
182	  // Which side of the bridge is active: the owner (English) or the phone call (German).
183	  const bridgeMode = question || !live ? 'you' : status === 'connected' ? 'call' : 'idle';
184	  const fill = (str) => {
185	    const out = str.replace('{name}', callee.short);
186	    return out.charAt(0).toUpperCase() + out.slice(1);
187	  };
188	  const bridgeNow = question
189	    ? t.nowAskingYou
190	    : !live
191	      ? t.nowDone
192	      : status === 'dialing'
193	        ? fill(t.nowDialing)
194	        : speaking === 'callee'
195	          ? fill(t.nowCalleeGerman)
196	          : fill(t.nowPawseGerman);
197	
198	  return (
199	    <main className="pc" ref={listRef}>
200	      {rail}
201	      <header className="pc-head">
202	        <div className={`pc-callee ${speaking === 'callee' ? 'talking' : ''} ${status === 'dialing' ? 'ringing' : ''}`}>
203	          <span aria-hidden="true">{callee.icon}</span>
204	        </div>
205	        <h1>{callee.name}</h1>
206	        <p className="muted">
207	          {callee.role} · {statusText}
208	        </p>
209	        <span className="sim-badge">{t.simulatedCall}</span>
210	        <ProviderChips t={t} items={phoneProviders({ live: IS_LIVE_PHONE, target, voice, browser })} />
211	      </header>
212	
213	      <section className={`bridge mode-${bridgeMode}`} aria-live="polite">
214	        <div className="bridge-side you">
215	          <span className="bridge-who">{t.you}</span>
216	          <span className="lang-tag">EN</span>
217	          <strong>{t.ownerLang}</strong>
